def build_element(spec):
    name, attributes, text, children = spec
    node = ET.Element(f"{{{SVG_NS}}}{name}", attributes)
    node.text = text
    object_id = attributes.get("id")
    if name == "g" and object_id in LAYERS:
        node.set(f"{{{INKSCAPE_NS}}}label", LAYERS[object_id])
        node.set(f"{{{INKSCAPE_NS}}}groupmode", "layer")
    for child in children:
        node.append(build_element(child))
    return node


def accent_path(font, size, code, x, y):
    font.set_size(size, 72)
    font.load_char(code)
    vertices, codes = font.get_path()
    parts = []
    for values, command in MathPath(vertices, codes).iter_segments():
        if command == MathPath.CLOSEPOLY:
            parts.append("Z")
            continue
        symbol = {MathPath.MOVETO: "M", MathPath.LINETO: "L",
                  MathPath.CURVE3: "Q", MathPath.CURVE4: "C"}[command]
        points = " ".join(f"{x + values[i]:.9g},{-y - values[i + 1]:.9g}"
                          for i in range(0, len(values), 2))
        parts.append(symbol + points)
    return " ".join(parts)


def add_formulas(root):
    parser = MathTextParser("path")
    for name, (expression, parent_id, cx, cy, max_width, max_height, font_size) in FORMULAS.items():
        parsed = parser.parse(expression, dpi=72, prop=FontProperties(size=100))
        scale = min(font_size / 100, max_width / parsed.width, max_height / parsed.height)
        x = cx - parsed.width * scale / 2
        y = cy + (parsed.height / 2 - parsed.depth) * scale
        parent = root.find(f".//*[@id='{parent_id}']")
        group = ET.SubElement(parent, f"{{{SVG_NS}}}g", {
            "id": f"{name}-formula", "data-latex": expression, "fill": "#040000",
            "transform": f"translate({x:.9g},{y:.9g}) scale({scale:.9g})",
        })
        for index, glyph in enumerate(parsed.glyphs, 1):
            font, size, code, *positions = glyph
            gx, gy = positions[-2:]
            identifier = f"{name}-glyph-{index:03d}"
            if unicodedata.category(chr(code)).startswith("M"):
                ET.SubElement(group, f"{{{SVG_NS}}}path", {
                    "id": identifier, "d": accent_path(font, size, code, gx, gy),
                })
            else:
                node = ET.SubElement(group, f"{{{SVG_NS}}}text", {
                    "id": identifier, "x": f"{gx:.9g}", "y": f"{-gy:.9g}",
                    "font-family": font.family_name, "font-size": f"{size:.9g}",
                    "font-style": "italic" if "italic" in font.style_name.lower() else "normal",
                    "font-weight": "bold" if "bold" in font.style_name.lower() else "normal",
                })
                node.text = chr(code)
        for index, (gx, gy, width, height) in enumerate(parsed.rects, 1):
            ET.SubElement(group, f"{{{SVG_NS}}}rect", {
                "id": f"{name}-fraction-bar-{index}", "x": f"{gx:.9g}", "y": f"{-gy - height:.9g}",
                "width": f"{width:.9g}", "height": f"{height:.9g}",
            })


def validate(root, formulas=False):
    counts = Counter(n.tag.rsplit("}", 1)[-1] for n in root.iter())
    if not formulas:
        expected = {"path": 197, "rect": 186, "line": 62, "polygon": 45,
                    "polyline": 2, "text": 40, "clipPath": 37}
        for name, count in expected.items():
            if counts[name] != count:
                raise ValueError(f"Missing or duplicated {name} objects: {counts[name]} != {count}")
    if root.get("viewBox") != "0 0 140.96 96.12":
        raise ValueError("The reference canvas and aspect ratio must be retained.")
    ids = [n.get("id") for n in root.iter() if n.get("id")]
    if len(ids) != len(set(ids)):
        raise ValueError("Every editable object must have a unique id.")
    if {"image", "foreignObject", "script", "use"}.intersection(counts):
        raise ValueError("The figure must contain native vector objects.")
    for node in root.iter():
        for key, value in node.attrib.items():
            if key.endswith("href") or "base64" in value or "data:image" in value:
                raise ValueError("External or embedded image references are not allowed.")
    labels = ["".join(n.itertext()) for n in root.iter(f"{{{SVG_NS}}}text")]
    required = {"Paired or aligned ", "multiomics inputs", "Shared sparse-regression engine",
                "Within each cell type or state", "TF-gene", "TF-region", "Region-gene",
                "TF-region-gene triplets", "Network outputs", "CRE", "Gene", "TSS links"}
    if not required.issubset(labels):
        raise ValueError(f"Missing text labels: {required.difference(labels)}")
    if formulas:
        for name, specification in FORMULAS.items():
            node = root.find(f".//*[@id='{name}-formula']")
            if node is None or node.get("data-latex") != specification[0]:
                raise ValueError(f"Missing mathematical formula: {name}")
    return counts


def dark_variant(root):
    dark = deepcopy(root)
    for node in dark.iter():
        for attribute in ("fill", "stroke"):
            color = node.get(attribute, "")
            if color.startswith("#") and len(color) == 7:
                node.set(attribute, "#" + "".join(
                    f"{255 - int(color[i:i + 2], 16):02x}" for i in (1, 3, 5)))
    dark.set("fill", "#ffffff")
    return dark


def write_svg(root, destination):
    ET.indent(root, space="  ")
    for text in root.iter(f"{{{SVG_NS}}}text"):
        if text.text is not None and not text.text.strip():
            text.text = None
        for span in text:
            if span.tail is not None and not span.tail.strip():
                span.tail = None
    temporary = destination.with_suffix(".svg.tmp")
    ET.ElementTree(root).write(temporary, encoding="utf-8", xml_declaration=True)
    temporary.replace(destination)


def draw():
    root = build_element(SCENE)
    validate(root)
    add_formulas(root)
    counts = validate(root, formulas=True)
    dark = dark_variant(root)
    validate(dark, formulas=True)
    OUTPUT.parent.mkdir(parents=True, exist_ok=True)
    write_svg(root, OUTPUT)
    write_svg(dark, OUTPUT.with_name(f"{OUTPUT.stem}-dark.svg"))
    for format_name in ("pdf", "png"):
        destination = OUTPUT.with_suffix(f".{format_name}")
        temporary = destination.with_suffix(destination.suffix + ".tmp")
        command = ["rsvg-convert", "--format", format_name]
        if format_name == "png":
            command.extend(["--width", "2400"])
        subprocess.run(command + ["--output", str(temporary), str(OUTPUT)], check=True,
                       env={**os.environ, "PANGOCAIRO_BACKEND": "fc"})
        temporary.replace(destination)
    print(f"{OUTPUT}: light/dark SVGs, PDF and PNG; {counts['text']} editable text objects")
    return OUTPUT


